DROP TABLE IF EXISTS `baggage`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `baggage` (
  `baggage_id` bigint NOT NULL AUTO_INCREMENT,
  `tag_number` varchar(60) NOT NULL,
  `actual_weight` decimal(6,2) NOT NULL,
  `barcode` varchar(100) DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'CHECKED_IN',
  `routing_path` text,
  PRIMARY KEY (`baggage_id`),
  UNIQUE KEY `uq_baggage_tag` (`tag_number`),
  UNIQUE KEY `barcode` (`barcode`),
  CONSTRAINT `ck_baggage_status` CHECK ((`status` in (_utf8mb4'CHECKED_IN',_utf8mb4'LOADED',_utf8mb4'TRANSIT',_utf8mb4'ARRIVED',_utf8mb4'LOST',_utf8mb4'CLAIMED'))),
  CONSTRAINT `ck_baggage_weight` CHECK ((`actual_weight` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=14053 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
