DROP TABLE IF EXISTS `baggage_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `baggage_log` (
  `flight_id` bigint NOT NULL,
  `passenger_id` bigint NOT NULL,
  `baggage_id` bigint NOT NULL,
  PRIMARY KEY (`flight_id`,`passenger_id`,`baggage_id`),
  KEY `idx_blog_passenger` (`passenger_id`),
  KEY `idx_blog_baggage` (`baggage_id`),
  CONSTRAINT `fk_baggage_log_baggage` FOREIGN KEY (`baggage_id`) REFERENCES `baggage` (`baggage_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_baggage_log_flight` FOREIGN KEY (`flight_id`) REFERENCES `flight` (`flight_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_baggage_log_passenger` FOREIGN KEY (`passenger_id`) REFERENCES `passenger` (`passenger_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
