--
-- Table structure for table `booking`
--

DROP TABLE IF EXISTS `booking`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `booking` (
  `ticket_no` bigint NOT NULL AUTO_INCREMENT,
  `flight_id` bigint NOT NULL,
  `passenger_id` bigint NOT NULL,
  `seat_no` varchar(10) NOT NULL,
  `class_name` varchar(20) NOT NULL,
  `is_transit` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`ticket_no`),
  UNIQUE KEY `uq_booking_one_seat_per_flight` (`flight_id`,`seat_no`),
  KEY `idx_booking_flight` (`flight_id`),
  KEY `idx_booking_passenger` (`passenger_id`),
  KEY `fk_booking_class` (`class_name`),
  CONSTRAINT `fk_booking_class` FOREIGN KEY (`class_name`) REFERENCES `travel_class` (`class_name`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_booking_flight` FOREIGN KEY (`flight_id`) REFERENCES `flight` (`flight_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_booking_passenger` FOREIGN KEY (`passenger_id`) REFERENCES `passenger` (`passenger_id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=20093 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

