DROP TABLE IF EXISTS `flight`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `flight` (
  `flight_id` bigint NOT NULL AUTO_INCREMENT,
  `flight_number` varchar(10) NOT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'SCHEDULED',
  `departure_time` datetime NOT NULL,
  `arrival_time` datetime NOT NULL,
  `airline_id` bigint NOT NULL,
  `aircraft_id` bigint NOT NULL,
  `departure_gate_id` bigint DEFAULT NULL,
  `arrival_gate_id` bigint DEFAULT NULL,
  `departure_airport_id` bigint NOT NULL,
  `arrival_airport_id` bigint NOT NULL,
  PRIMARY KEY (`flight_id`),
  KEY `idx_flight_times` (`departure_time`,`arrival_time`),
  KEY `idx_flight_airline` (`airline_id`),
  KEY `idx_flight_aircraft` (`aircraft_id`),
  KEY `idx_flight_dep_gate` (`departure_gate_id`),
  KEY `idx_flight_arr_gate` (`arrival_gate_id`),
  KEY `fk_flight_dep_airport` (`departure_airport_id`),
  KEY `fk_flight_arr_airport` (`arrival_airport_id`),
  CONSTRAINT `fk_flight_aircraft` FOREIGN KEY (`aircraft_id`) REFERENCES `aircraft` (`aircraft_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_flight_airline` FOREIGN KEY (`airline_id`) REFERENCES `airline` (`airline_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_flight_arr_airport` FOREIGN KEY (`arrival_airport_id`) REFERENCES `airport` (`airport_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_flight_arr_gate` FOREIGN KEY (`arrival_gate_id`) REFERENCES `gate` (`gate_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_flight_dep_airport` FOREIGN KEY (`departure_airport_id`) REFERENCES `airport` (`airport_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_flight_dep_gate` FOREIGN KEY (`departure_gate_id`) REFERENCES `gate` (`gate_id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `ck_flight_status` CHECK ((`status` in (_utf8mb4'SCHEDULED',_utf8mb4'BOARDING',_utf8mb4'GATE_CLOSED',_utf8mb4'DELAYED',_utf8mb4'DEPARTED',_utf8mb4'LANDED',_utf8mb4'CANCELLED',_utf8mb4'DIVERTED')))
) ENGINE=InnoDB AUTO_INCREMENT=5491 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
