--
-- Table structure for table `security_log`
--

DROP TABLE IF EXISTS `security_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `security_log` (
  `check_id` bigint NOT NULL AUTO_INCREMENT,
  `type_of_check` varchar(80) NOT NULL,
  `date` datetime NOT NULL,
  `staff_id` bigint NOT NULL,
  `passenger_id` bigint NOT NULL,
  `status` varchar(30) NOT NULL,
  PRIMARY KEY (`check_id`),
  KEY `idx_security_staff` (`staff_id`),
  KEY `idx_security_passenger` (`passenger_id`),
  CONSTRAINT `fk_security_log_passenger` FOREIGN KEY (`passenger_id`) REFERENCES `passenger` (`passenger_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_security_log_staff` FOREIGN KEY (`staff_id`) REFERENCES `staff` (`staff_id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `ck_security_status` CHECK ((`status` in (_utf8mb4'PASSED',_utf8mb4'FAILED',_utf8mb4'PENDING')))
) ENGINE=InnoDB AUTO_INCREMENT=301 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

